{
  "title": "The Glass Diver's Rescue",
  "scenes": [
    {
      "scene_number": 1,
      "caption": "Mara the Cartographer studies a ruined city map.",
      "visual_description": "Mara stands on a hill overlooking the broken skyline of the ruined royal city, unfurling a tattered map with ink stains and compass lines.",
      "characters": ["mara_the_cartographer"]
    },
    {
      "scene_number": 2,
      "caption": "The glass_diver emerges from a cracked mirror.",
      "visual_description": "A clear diving helmet reflects shards of light as the glass_diver steps out of a tall, shattered mirror propped against a collapsed wall.",
      "characters": ["glass_diver", "mara_the_cartographer"]
    },
    {
      "scene_number": 3,
      "caption": "The oracle_lamp flickers a warning near the castle gates.",
      "visual_description": "At the rusted iron castle gates, the oracle_lamp sits on a stone, its single flame-eye glowing as it casts shifting shadows on the barred entrance.",
      "characters": ["oracle_lamp", "glass_diver", "mara_the_cartographer"]
    },
    {
      "scene_number": 4,
      "caption": "The tin_fox scouts the broken courtyard.",
      "visual_description": "The small metal fox with a key-wind tail and blue glass eyes darts across a courtyard littered with rubble and faded royal banners.",
      "characters": ["tin_fox"]
    },
    {
      "scene_number": 5,
      "caption": "The sleeping_tax_collector snores behind a ledger.",
      "visual_description": "In a dusty alcove, the sleeping_tax_collector uses a ledger book as a pillow, stamped papers stuck to his sleeves, oblivious to the group's approach.",
      "characters": ["sleeping_tax_collector", "mara_the_cartographer", "glass_diver"]
    },
    {
      "scene_number": 6,
      "caption": "Mara traces a path around a cursed tower.",
      "visual_description": "Mara points to a spiraling tower with dark, shimmering windows, her compass needle spinning wildly as she marks a detour on her map.",
      "characters": ["mara_the_cartographer", "glass_diver", "tin_fox"]
    },
    {
      "scene_number": 7,
      "caption": "The glass_diver peers into a murky fountain.",
      "visual_description": "Beneath a broken statue, the glass_diver leans over a moss-filled fountain, his helmet reflecting the distorted image of a hidden passage.",
      "characters": ["glass_diver", "oracle_lamp"]
    },
    {
      "scene_number": 8,
      "caption": "The oracle_lamp warns of armored patrols.",
      "visual_description": "The oracle_lamp's flame-eye narrows as it casts a red light on a distant street where figure shapes move in unison under rusted armor.",
      "characters": ["oracle_lamp", "glass_diver", "mara_the_cartographer", "tin_fox"]
    },
    {
      "scene_number": 9,
      "caption": "The tin_fox triggers a hidden trap.",
      "visual_description": "The clockwork fox steps on a loose stone, and a net of old royal banners drops from above, wrapping around the fox's metal limbs.",
      "characters": ["tin_fox", "glass_diver", "mara_the_cartographer"]
    },
    {
      "scene_number": 10,
      "caption": "Mara cuts the tin_fox free with a map edge.",
      "visual_description": "Mara uses the sharp edge of her rolled map to slice through the banner ropes, freeing the tin_fox while the glass_diver watches for patrols.",
      "characters": ["mara_the_cartographer", "tin_fox", "glass_diver"]
    },
    {
      "scene_number": 11,
      "caption": "The group approaches a magic door.",
      "visual_description": "A door of polished obsidian stands in a stone archway, its surface rippling with faint light as the oracle_lamp casts a beam across it.",
      "characters": ["oracle_lamp", "mara_the_cartographer", "glass_diver", "tin_fox"]
    },
    {
      "scene_number": 12,
      "caption": "The sleeping_tax_collector wakes briefly to stamp a form.",
      "visual_description": "Startled by noise, the sleeping_tax_collector sits up, stamps a random piece of paper, then slumps back onto his ledger pillow.",
      "characters": ["sleeping_tax_collector", "mara_the_cartographer"]
    },
    {
      "scene_number": 13,
      "caption": "The glass_diver swims through the magic door's surface.",
      "visual_description": "The glass_diver presses his helmet against the obsidian door and passes through like a diver into water, emerging on the other side.",
      "characters": ["glass_diver", "mara_the_cartographer", "tin_fox", "oracle_lamp"]
    },
    {
      "scene_number": 14,
      "caption": "Mara reads a riddle on the far wall.",
      "visual_description": "Inside a sealed chamber, Mara traces her fingers over glowing runes on a stone wall, her lips moving as she deciphers the message.",
      "characters": ["mara_the_cartographer", "glass_diver", "tin_fox"]
    },
    {
      "scene_number": 15,
      "caption": "The oracle_lamp reveals a hidden staircase.",
      "visual_description": "The oracle_lamp's flame-eye brightens, casting a pattern on the floor that reveals spiral stairs concealed beneath dust and rubble.",
      "characters": ["oracle_lamp", "glass_diver", "mara_the_cartographer"]
    },
    {
      "scene_number": 16,
      "caption": "The tin_fox leads the way to the bridge.",
      "visual_description": "The clockwork fox scampers ahead, its blue eyes glowing as it navigates through a narrow alley toward a stone bridge over a dry moat.",
      "characters": ["tin_fox", "mara_the_cartographer", "glass_diver", "oracle_lamp"]
    },
    {
      "scene_number": 17,
      "caption": "The group races across the bridge.",
      "visual_description": "Under a pale sky, the four figures sprint across the ancient bridge, its broken balustrades and fading royal banners whipping in the wind.",
      "characters": ["glass_diver", "mara_the_cartographer", "oracle_lamp", "tin_fox"]
    },
    {
      "scene_number": 18,
      "caption": "The glass_diver dives into a final mirror to escape.",
      "visual_description": "At the far end of the bridge, the glass_diver leaps into a tall standing mirror, the surface rippling as he disappears, followed by the others one by one.",
      "characters": ["glass_diver", "mara_the_cartographer", "oracle_lamp", "tin_fox"]
    }
  ],
  "gate_token": "zFuai3h8SvcZI5JwikOWEg"
}

